using System.Globalization;
using LibraryService.Data;
using LibraryService.Models;
using LibraryService.Services;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

// HTTP endpoints exposed by library-service.
namespace LibraryService.Controllers;

/// <summary>
/// Manages the favorites of one anonymous browser, identified by the
/// X-Client-Id header (a GUID generated by the frontend).
/// This is not real authentication: whoever knows the GUID can use it.
/// </summary>
[ApiController]
[Route("favorites")]
public class FavoritesController(LibraryDbContext db, CatalogClient catalog) : ControllerBase
{
    private const string ClientIdHeader = "X-Client-Id";

    /// <summary>Lists all favorites of the caller, newest first. No pagination.</summary>
    /// <param name="clientId">Browser ID, read from the X-Client-Id header.</param>
    /// <param name="ct">Cancels the query if the browser disconnects.</param>
    /// <returns>200 with the list (possibly empty), or 400 if the header is missing.</returns>
    [HttpGet]
    public async Task<ActionResult<List<FavoriteDto>>> List(
        [FromHeader(Name = ClientIdHeader)] Guid clientId, CancellationToken ct)
    {
        if (clientId == Guid.Empty) return MissingClientId();

        return await db.Favorites
            .Where(f => f.ClientId == clientId)
            .OrderByDescending(f => f.AddedAtUtc)
            .Select(f => new FavoriteDto(f.GameId, f.Name, f.CoverUrl, f.Rating, f.ReleaseDate, f.AddedAtUtc))
            .ToListAsync(ct);
    }

    /// <summary>Checks whether one game is a favorite of the caller.</summary>
    /// <param name="gameId">RAWG's ID of the game.</param>
    /// <param name="clientId">Browser ID, read from the X-Client-Id header.</param>
    /// <param name="ct">Cancels the query if the browser disconnects.</param>
    /// <returns>200 with the favorite if it exists, 404 if not, 400 if the header is missing.</returns>
    [HttpGet("{gameId:int}")]
    public async Task<ActionResult<FavoriteDto>> Get(
        int gameId, [FromHeader(Name = ClientIdHeader)] Guid clientId, CancellationToken ct)
    {
        if (clientId == Guid.Empty) return MissingClientId();

        var favorite = await db.Favorites
            .Where(f => f.ClientId == clientId && f.GameId == gameId)
            .Select(f => new FavoriteDto(f.GameId, f.Name, f.CoverUrl, f.Rating, f.ReleaseDate, f.AddedAtUtc))
            .FirstOrDefaultAsync(ct);

        return favorite is null ? NotFound() : favorite;
    }

    /// <summary>
    /// Adds a game to the favorites. If it is already there, does nothing.
    /// Otherwise it fetches the game from catalog-service and saves a snapshot.
    /// </summary>
    /// <param name="gameId">RAWG's ID of the game.</param>
    /// <param name="clientId">Browser ID, read from the X-Client-Id header.</param>
    /// <param name="ct">Cancels the work if the browser disconnects.</param>
    /// <returns>204 on success or repeat, 404 if the game doesn't exist, 502 if the catalog is unreachable.</returns>
    [HttpPut("{gameId:int}")]
    public async Task<IActionResult> Add(
        int gameId, [FromHeader(Name = ClientIdHeader)] Guid clientId, CancellationToken ct)
    {
        if (clientId == Guid.Empty) return MissingClientId();

        // Already saved: skip the catalog call (and the RAWG request it would cost).
        if (await Exists(clientId, gameId, ct)) return NoContent();

        CatalogGame? game;
        try
        {
            game = await catalog.GetGameAsync(gameId, ct);
        }
        catch (Exception ex) when (ex is HttpRequestException or TaskCanceledException)
        {
            return StatusCode(StatusCodes.Status502BadGateway, "The catalog service is unavailable.");
        }

        if (game is null) return NotFound($"Game {gameId} does not exist.");

        db.Favorites.Add(new FavoriteGame
        {
            ClientId = clientId,
            GameId = game.Id,
            Name = game.Name,
            CoverUrl = game.BackgroundImage,
            Rating = game.Rating,
            ReleaseDate = DateOnly.TryParseExact(game.Released, "yyyy-MM-dd",
                CultureInfo.InvariantCulture, DateTimeStyles.None, out var date) ? date : null,
            AddedAtUtc = DateTime.UtcNow
        });

        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException)
        {
            // Two identical requests raced and the primary key rejected the second one.
            // That's the "already favorite" case; anything else is a real error.
            if (!await Exists(clientId, gameId, ct)) throw;
        }

        return NoContent();
    }

    /// <summary>Removes a game from the favorites. Removing a missing one is not an error.</summary>
    /// <param name="gameId">RAWG's ID of the game.</param>
    /// <param name="clientId">Browser ID, read from the X-Client-Id header.</param>
    /// <param name="ct">Cancels the work if the browser disconnects.</param>
    /// <returns>204 always, or 400 if the header is missing.</returns>
    [HttpDelete("{gameId:int}")]
    public async Task<IActionResult> Remove(
        int gameId, [FromHeader(Name = ClientIdHeader)] Guid clientId, CancellationToken ct)
    {
        if (clientId == Guid.Empty) return MissingClientId();

        // Runs a single DELETE ... WHERE statement, without loading the row first.
        await db.Favorites
            .Where(f => f.ClientId == clientId && f.GameId == gameId)
            .ExecuteDeleteAsync(ct);

        return NoContent();
    }

    /// <summary>Tells whether the caller already has this game in the favorites.</summary>
    private Task<bool> Exists(Guid clientId, int gameId, CancellationToken ct) =>
        db.Favorites.AnyAsync(f => f.ClientId == clientId && f.GameId == gameId, ct);

    /// <summary>Builds the 400 response used when the X-Client-Id header is absent or empty.</summary>
    private BadRequestObjectResult MissingClientId() =>
        BadRequest($"The {ClientIdHeader} header is required and must be a non-empty GUID.");
}
